import argparse,hashlib,importlib.util,json
from pathlib import Path
import numpy as np
R=Path(__file__).parent; A=R.parent/"e1-qk-numerical-audit-20260906"
spec=importlib.util.spec_from_file_location("base",A/"compare-block.py");C=importlib.util.module_from_spec(spec);spec.loader.exec_module(C)
def check(cr,cv,raw,vals):
 for k in ["in.kvlen","act.q","kv.5.k","kv.5.v"]:assert raw[k]==cr[k],(k,"upstream differs")
 m={k:C.metrics(cv[k],vals[k]) for k in ["act.opart","act.mlpart","act.at","act.x"]}
 assert m["act.at"]["relative_l2"]<=.003,("attention",m["act.at"])
 assert m["act.x"]["relative_l2"]<=.01 and m["act.x"]["max_abs"]<=.05+.02*m["act.x"]["max_ref"],("block",m["act.x"])
 return m
def self_test():
 C.self_test(); raw={k:b"x" for k in ["in.kvlen","act.q","kv.5.k","kv.5.v"]}; vals={k:np.array([1.]) for k in ["act.opart","act.mlpart","act.at","act.x"]}
 check(raw,vals,raw,vals)
 bad=[]
 r=dict(raw);r["act.q"]=b"y";bad.append((r,vals))
 for key,value in [("act.at",1.004),("act.x",1.011),("act.x",float("nan"))]:
  v=dict(vals);v[key]=np.array([value]);bad.append((raw,v))
 for r,v in bad:
  try:check(raw,vals,r,v)
  except AssertionError:pass
  else:raise AssertionError("negative fixture accepted")
 print("PASS unchanged gates, upstream mutation, attention/block excess, nonfinite rejection")
def run():
 for name in ["input-provenance.json","saved-input-provenance.json"]:
  obj=json.loads((R/name).read_text());files=obj.get("files",obj)
  for p,d in files.items():assert hashlib.sha256(Path(p).read_bytes()).hexdigest()==d["sha256"],p
 for p,d in json.loads((R/"FREEZE.json").read_text())["files"].items():assert hashlib.sha256((R/p).read_bytes()).hexdigest()==d["sha256"],p
 native=C.load("control"); qk=C.load("qk-only"); C.R=R; candidate=C.load("k64")
 assert len(native)==len(qk)==len(candidate)==6
 records=[]
 for step,((cr,cv),(raw,vals)) in enumerate(zip(native,candidate)):
  metric=check(cr,cv,raw,vals)
  replay=R/"results/operator-numerical-tensors"/f"candidate-step{step%3}-out.raw"
  assert raw["act.at"]==replay.read_bytes(),(step,"broad output differs from same-input DSO")
  records.append(dict(step=step,upstream_exact=True,repeats_exact=True,saved_operator_output_exact=True,metrics=metric,previous_qk_metrics={k:C.metrics(cv[k],qk[step][1][k]) for k in metric}))
 out=dict(passed=True,data_valid=True,numerical_pass=True,rows=6,records=records,scope="Native single-block numerical gate; unchanged .003 attention/.01 block plus original maxabs gate. No full-model or timing qualification.")
 (R/"results/block-numerical.json").write_text(json.dumps(out,indent=2)+"\n");print(json.dumps(dict(passed=True,rows=6,max_block_rel_l2=max(r["metrics"]["act.x"]["relative_l2"] for r in records))))
if __name__=="__main__":
 p=argparse.ArgumentParser();p.add_argument("--self-test",action="store_true");a=p.parse_args()
 if a.self_test:self_test()
 else:run()
